## 四、组件测试脚本

### LoginView 测试脚本

```typescript
// tests/views/LoginView.spec.ts
import { mount } from '@vue/test-utils'
import { createPinia, setActivePinia } from 'pinia'
import { createRouter, createMemoryHistory } from 'vue-router'
import LoginView from '@/views/auth/LoginView.vue'

describe('LoginView', () => {
  let router: any

  beforeEach(() => {
    setActivePinia(createPinia())
    router = createRouter({
      history: createMemoryHistory(),
      routes: [{ path: '/login', component: LoginView, meta: { guest: true } }]
    })
  })

  // ===== UI 测试 =====
  it('应渲染邮箱和密码输入框', () => {
    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('input[type="email"]').exists()).toBe(true)
    expect(wrapper.find('input[type="password"]').exists()).toBe(true)
  })

  it('应显示登录按钮', () => {
    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    const btn = wrapper.find('button[type="submit"]')
    expect(btn.exists()).toBe(true)
  })

  it('邮箱为空时显示校验错误', async () => {
    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    const emailInput = wrapper.find('input[type="email"]')
    await emailInput.setValue('')
    await emailInput.trigger('blur')
    // 应有错误提示
    expect(wrapper.find('.form-input__error').exists()).toBe(true)
  })

  it('邮箱格式不正确时显示校验错误', async () => {
    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    const emailInput = wrapper.find('input[type="email"]')
    await emailInput.setValue('invalid-email')
    await emailInput.trigger('blur')
    expect(wrapper.text()).toContain('邮箱格式不正确')
  })

  it('密码少于6位时显示校验错误', async () => {
    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    const pwdInput = wrapper.find('input[type="password"]')
    await pwdInput.setValue('123')
    await pwdInput.trigger('blur')
    expect(wrapper.text()).toContain('密码至少6位')
  })

  // ===== 交互测试 =====
  it('提交时按钮进入 loading 状态', async () => {
    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    await wrapper.find('input[type="email"]').setValue('test@test.com')
    await wrapper.find('input[type="password"]').setValue('Test123')
    await wrapper.find('form').trigger('submit.prevent')
    // 按钮应变为 disabled
    const btn = wrapper.find('button[type="submit"]')
    expect(btn.attributes('disabled')).toBeDefined()
  })

  it('支持验证码登录模式切换', async () => {
    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    // 点击切换为验证码登录
    const toggleBtn = wrapper.find('[data-test="toggle-code-mode"]')
    if (toggleBtn.exists()) {
      await toggleBtn.trigger('click')
      expect(wrapper.find('input[placeholder*="验证码"]').exists()).toBe(true)
    }
  })

  // ===== 功能测试 =====
  it('登录成功应调用 authStore.login', async () => {
    const authStore = useAuthStore()
    const loginSpy = vi.spyOn(authStore, 'login').mockResolvedValue(undefined)

    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    await wrapper.find('input[type="email"]').setValue('student@test.com')
    await wrapper.find('input[type="password"]').setValue('Test1234')
    await wrapper.find('form').trigger('submit.prevent')

    expect(loginSpy).toHaveBeenCalledWith({
      email: 'student@test.com',
      password: 'Test1234',
      type: 'password'
    })
  })

  it('登录失败应显示错误消息', async () => {
    const authStore = useAuthStore()
    vi.spyOn(authStore, 'login').mockRejectedValue(new Error('密码错误'))

    const wrapper = mount(LoginView, { global: { plugins: [createPinia(), router] } })
    await wrapper.find('input[type="email"]').setValue('test@test.com')
    await wrapper.find('input[type="password"]').setValue('wrong')
    await wrapper.find('form').trigger('submit.prevent')

    await wrapper.vm.$nextTick()
    expect(wrapper.text()).toContain('密码错误')
  })
})
```

### HomeView 测试脚本

```typescript
// tests/views/HomeView.spec.ts
import { mount } from '@vue/test-utils'
import { createPinia, setActivePinia } from 'pinia'
import { createRouter, createMemoryHistory } from 'vue-router'
import HomeView from '@/views/student/HomeView.vue'

// Mock 子组件
vi.mock('@/components/business/RadarChart.vue', () => ({
  default: { template: '<div class="mock-radar-chart"></div>', props: ['data'] }
}))
vi.mock('@/components/business/KnowledgeTreeMap.vue', () => ({
  default: { template: '<div class="mock-tree-map"></div>', props: ['data'] }
}))
vi.mock('@/components/business/ProfileCard.vue', () => ({
  default: { template: '<div class="mock-profile-card"></div>', props: ['profile'] }
}))
vi.mock('@/components/business/TaskList.vue', () => ({
  default: { template: '<div class="mock-task-list"></div>', props: ['tasks'] }
}))

describe('HomeView', () => {
  let router: any

  beforeEach(() => {
    setActivePinia(createPinia())
    router = createRouter({
      history: createMemoryHistory(),
      routes: [
        { path: '/student/home', component: HomeView, meta: { title: '学习首页', role: 'student' } },
        { path: '/student/practice', component: {}, name: 'StudentPractice' },
        { path: '/student/exam', component: {}, name: 'StudentExam' },
        { path: '/student/ai-qa', component: {}, name: 'StudentAiQA' },
        { path: '/student/error-book', component: {}, name: 'StudentErrorBook' },
      ]
    })
  })

  // ===== UI 测试 =====
  it('应渲染三栏布局', () => {
    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('.home-grid').exists()).toBe(true)
  })

  it('应渲染 ProfileCard 组件', () => {
    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('.mock-profile-card').exists()).toBe(true)
  })

  it('应渲染 TaskList 组件', () => {
    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('.mock-task-list').exists()).toBe(true)
  })

  it('应渲染 RadarChart 组件', () => {
    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('.mock-radar-chart').exists()).toBe(true)
  })

  it('应渲染 KnowledgeTreeMap 组件', () => {
    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('.mock-tree-map').exists()).toBe(true)
  })

  it('应显示4个快捷入口按钮', () => {
    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    const quickBtns = wrapper.findAll('.quick-btn')
    expect(quickBtns.length).toBe(4)
    expect(quickBtns[0].text()).toContain('开始练习')
    expect(quickBtns[1].text()).toContain('模拟考试')
    expect(quickBtns[2].text()).toContain('AI问答')
    expect(quickBtns[3].text()).toContain('错题本')
  })

  // ===== 交互测试 =====
  it('快捷入口点击应跳转到正确路由', async () => {
    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    await router.isReady()

    const quickBtns = wrapper.findAll('.quick-btn')
    await quickBtns[0].trigger('click')
    await wrapper.vm.$nextTick()
    // 验证路由跳转
    expect(router.currentRoute.value.path).toBe('/student/practice')
  })

  it('冲刺模式关闭时不显示冲刺卡片', () => {
    const studentStore = useStudentStore()
    studentStore.isSprintMode = false

    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('.sprint-card').exists()).toBe(false)
  })

  it('冲刺模式开启时显示冲刺卡片', () => {
    const studentStore = useStudentStore()
    studentStore.isSprintMode = true
    studentStore.daysUntilExam = 7

    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('.sprint-card').exists()).toBe(true)
    expect(wrapper.text()).toContain('7')
  })

  // ===== 功能测试 =====
  it('onMounted 应并行调用三个 fetch 方法', async () => {
    const studentStore = useStudentStore()
    const fetchProfileSpy = vi.spyOn(studentStore, 'fetchProfile').mockResolvedValue(undefined)
    const fetchDashboardSpy = vi.spyOn(studentStore, 'fetchDashboard').mockResolvedValue(undefined)
    const fetchTasksSpy = vi.spyOn(studentStore, 'fetchTodayTasks').mockResolvedValue(undefined)

    mount(HomeView, { global: { plugins: [createPinia(), router] } })
    await nextTick()

    expect(fetchProfileSpy).toHaveBeenCalled()
    expect(fetchDashboardSpy).toHaveBeenCalled()
    expect(fetchTasksSpy).toHaveBeenCalled()
  })

  it('数据加载中应显示 LoadingSpinner', () => {
    const studentStore = useStudentStore()
    studentStore.loading = true

    const wrapper = mount(HomeView, { global: { plugins: [createPinia(), router] } })
    expect(wrapper.find('.loading-spinner').exists() || wrapper.text().includes('加载中')).toBe(true)
  })
})
```

### 集成测试脚本

```typescript
// tests/integration/login-to-home.spec.ts
import { mount } from '@vue/test-utils'
import { createPinia, setActivePinia } from 'pinia'
import { createRouter, createMemoryHistory } from 'vue-router'

describe('Login → Home 集成测试', () => {
  it('学员登录后应自动跳转到学习首页', async () => {
    const authStore = useAuthStore()

    // 模拟登录成功
    authStore.token = 'mock-jwt-token'
    authStore.userInfo = {
      id: 1, email: 'student@test.com', role: 'student',
      name: '测试学员', carType: 'C1', schoolName: '测试驾校'
    }

    const router = createRouter({
      history: createMemoryHistory(),
      routes: [
        { path: '/login', name: 'Login', meta: { guest: true } },
        { path: '/student/home', name: 'StudentHome', meta: { role: 'student' } }
      ]
    })

    await router.push('/login')
    await router.isReady()

    // guest 路由守卫应自动重定向
    if (authStore.isAuthenticated) {
      expect(router.currentRoute.value.path).toBe('/student/home')
    }
  })

  it('HomeView 应校验 student 角色', async () => {
    const authStore = useAuthStore()
    authStore.userInfo = { id: 2, role: 'coach' } // 非 student 角色

    const router = createRouter({
      history: createMemoryHistory(),
      routes: [
        { path: '/student/home', name: 'StudentHome', meta: { role: 'student' } },
        { path: '/forbidden', name: 'Forbidden' }
      ]
    })

    await router.push('/student/home')
    await router.isReady()

    // coach 不能访问 student 页面
    expect(router.currentRoute.value.name).toBe('Forbidden')
  })
})
```

